/* Generated by scripts/generate-registry.mjs — do not edit. */
@import "./tokens.css";
@import "./base.css";
@import "./tactile-controls.css";
@import "./ui-primitives.css";
@import "./portals-overlays.css";

@custom-variant dark (&:is(.dark *));

/* ------------------------------------------------------------------
   Kinetic UI design tokens — single source of truth.

   The Kinetic material palette (surfaces, text, borders, shadows)
   is defined once per theme here. shadcn's semantic tokens are
   derived from the same palette, so the custom CSS and the shadcn
   component system share one set of values instead of two parallel
   palettes.
------------------------------------------------------------------- */

:root {
  color-scheme: light;

  /* Fonts (bundled locally via Fontsource) */
  --font-dot-gothic: "DotGothic16";
  --font-geist-sans: "Geist";
  --font-geist-mono: "Geist Mono";

  /* Radii */
  --radius: 0.625rem;
  --kinetic-radius-xs: 6px;
  --kinetic-radius-sm: 8px;
  --kinetic-radius-control: 10px;
  --kinetic-radius-menu: 14px;
  --kinetic-radius-panel: 18px;
  --kinetic-radius-pill: 999px;

  /* Shared control sizing. Compact and icon variants opt into the smaller
     values below, while ordinary actions use one tactile touch target. */
  --kinetic-control-height: 40px;
  --kinetic-control-height-compact: 36px;
  --kinetic-control-height-small: 32px;

  /* Type scale (minimum readable sizes; smaller sizes are reserved for
     miniature previews and badges only) */
  --text-2xs: 11px;
  --text-xs: 12px;
  --text-sm: 13px;
  --text-md: 14px;
  --text-lg: 16px;
  --text-xl: 18px;

  /* Spacing scale */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-7: 32px;

  /* Kinetic material palette (light) */
  --bg: #e8e6df;
  --bg-deep: #d8d5cc;
  --bg-soft: #eeece5;
  --sidebar: #e0ded7;
  --surface-top: #fffefa;
  --surface-mid: #f2f0e9;
  --surface-bottom: #d8d6cf;
  --surface-flat: #eceae3;
  --surface-hover: #fffefa;
  --surface-inset: #d8d6cf;
  --border: rgba(35, 35, 32, 0.16);
  --border-soft: rgba(35, 35, 32, 0.1);
  --edge-light: rgba(255, 255, 255, 0.84);
  --text: #242522;
  --text-soft: #555651;
  --text-muted: #595a55;
  --accent: #ef5a1d;
  --accent-dark: #c83e0d;
  --action-top: #c94a16;
  --action-bottom: #9f3008;
  --action-foreground: #fff;
  --accent-soft: rgba(239, 90, 29, 0.12);
  --accent-glow: rgba(239, 90, 29, 0.2);
  --success: #238a5b;
  --warning: #aa6a0a;
  --danger: #b91c1c;
  --info: #2f73d9;
  --chart-grid: rgba(35, 35, 32, 0.13);
  --chart-track: #d2cfc6;
  --chart-hover: rgba(35, 35, 32, 0.045);
  --shadow-raised: inset 0 1px 0 rgba(255, 255, 255, 0.95), inset 0 -1px 0 rgba(69, 66, 58, 0.18);
  --shadow-soft: 0 9px 24px rgba(61, 57, 47, 0.13), inset 0 1px 0 rgba(255, 255, 255, 0.9);
  --shadow-control:
    0 4px 9px rgba(60, 57, 50, 0.18), inset 0 1px 0 #fff, inset 0 -1px 0 rgba(55, 52, 46, 0.16);
  --shadow-inset: inset 0 2px 5px rgba(70, 67, 59, 0.18), inset 0 -1px 0 rgba(255, 255, 255, 0.85);
  --shadow-overlay:
    0 28px 64px rgba(61, 57, 47, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.95),
    inset 0 -1px 0 rgba(69, 66, 58, 0.14);

  /* Focus ring (WCAG 2.1 AA keyboard navigation) */
  --focus-ring: var(--accent);
  --focus-ring-width: 2px;
  --focus-ring-offset: 2px;

  /* shadcn semantic tokens, derived from the Kinetic palette */
  --background: var(--bg);
  --foreground: var(--text);
  --card: var(--surface-mid);
  --card-foreground: var(--text);
  --popover: var(--surface-mid);
  --popover-foreground: var(--text);
  --primary: var(--accent-dark);
  --primary-foreground: #fff;
  --secondary: var(--surface-flat);
  --secondary-foreground: var(--text);
  --muted: var(--surface-inset);
  --muted-foreground: var(--text-muted);
  --accent-foreground: #fff;
  --destructive: var(--danger);
  --input: var(--border);
  --ring: var(--accent);
  --sidebar-foreground: var(--text);
  --sidebar-primary: var(--accent-dark);
  --sidebar-primary-foreground: #fff;
  --sidebar-accent: var(--surface-hover);
  --sidebar-accent-foreground: var(--text);
  --sidebar-border: var(--border);
  --sidebar-ring: var(--accent);

  /* Chart hues (independent of the material surfaces) */
  --chart-1: hsl(17 82% 42%);
  --chart-2: hsl(214 67% 52%);
  --chart-3: hsl(153 60% 34%);
  --chart-4: hsl(37 89% 35%);
  --chart-5: hsl(0 50% 49%);
}

.dark {
  color-scheme: dark;

  /* Kinetic material palette (dark) */
  --bg: #101214;
  --bg-deep: #0b0d0f;
  --bg-soft: #17191c;
  --sidebar: #121416;
  --surface-top: #25282b;
  --surface-mid: #1e2023;
  --surface-bottom: #17191b;
  --surface-flat: #1a1c1f;
  --surface-hover: #292c2f;
  --surface-inset: #111315;
  --border: rgba(255, 255, 255, 0.095);
  --border-soft: rgba(255, 255, 255, 0.06);
  --edge-light: rgba(255, 255, 255, 0.08);
  --text: #f4f2eb;
  --text-soft: #bbb8b0;
  --text-muted: #7e7d78;
  --accent: #ff6a2a;
  --accent-dark: #d94813;
  --action-top: #ff783e;
  --action-bottom: var(--accent-dark);
  --action-foreground: #fff9f5;
  --accent-soft: rgba(255, 106, 42, 0.14);
  --accent-glow: rgba(255, 96, 31, 0.28);
  --success: #45b87f;
  --warning: #e8a33d;
  --danger: #dc2626;
  --info: #559bff;
  --chart-grid: rgba(255, 255, 255, 0.075);
  --chart-track: #2a2d30;
  --chart-hover: rgba(255, 255, 255, 0.035);
  --shadow-raised: inset 0 1px 0 rgba(255, 255, 255, 0.065), inset 0 -1px 0 rgba(0, 0, 0, 0.48);
  --shadow-soft: 0 10px 28px rgba(0, 0, 0, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.055);
  --shadow-control:
    0 5px 12px rgba(0, 0, 0, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.09),
    inset 0 -1px 0 rgba(0, 0, 0, 0.52);
  --shadow-inset: inset 0 2px 5px rgba(0, 0, 0, 0.58), inset 0 -1px 0 rgba(255, 255, 255, 0.08);
  --shadow-overlay:
    0 28px 64px rgba(0, 0, 0, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.38),
    inset 0 -1px 0 rgba(0, 0, 0, 0.22);

  /* Focus ring (WCAG 2.1 AA keyboard navigation) */
  --focus-ring: var(--accent);
  --focus-ring-width: 2px;
  --focus-ring-offset: 2px;

  /* shadcn semantic tokens, derived from the Kinetic palette */
  --background: var(--bg);
  --foreground: var(--text);
  --card: var(--surface-mid);
  --card-foreground: var(--text);
  --popover: var(--surface-mid);
  --popover-foreground: var(--text);
  --primary: var(--accent-dark);
  --primary-foreground: #fff;
  --secondary: var(--surface-flat);
  --secondary-foreground: var(--text);
  --muted: var(--surface-inset);
  --muted-foreground: var(--text-muted);
  --accent-foreground: #fff;
  --destructive: var(--danger);
  --input: var(--border);
  --ring: var(--accent);
  --sidebar-foreground: var(--text);
  --sidebar-primary: var(--accent-dark);
  --sidebar-primary-foreground: #fff;
  --sidebar-accent: var(--surface-hover);
  --sidebar-accent-foreground: var(--text);
  --sidebar-border: var(--border);
  --sidebar-ring: var(--accent);

  /* Chart hues (independent of the material surfaces) */
  --chart-1: hsl(17 82% 44%);
  --chart-2: hsl(214 100% 67%);
  --chart-3: hsl(153 45% 50%);
  --chart-4: hsl(37 79% 57%);
  --chart-5: hsl(0 70% 63%);
}

@theme inline {
  --font-heading: var(--font-sans);
  --font-sans: "Geist", sans-serif;
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --color-foreground: var(--foreground);
  --color-background: var(--background);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}

* {
  box-sizing: border-box;
}
html {
  /* Section navigation is driven explicitly so anchors do not crawl through
     the full catalog when returning to the top of the page. */
  scroll-behavior: auto;
}
html,
body {
  min-height: 100%;
  margin: 0;
}
body {
  background: var(--background);
  font-family: var(--font-geist-sans), Arial, Helvetica, sans-serif;
}
button,
input,
select {
  font: inherit;
}
button,
a,
input,
select {
  -webkit-tap-highlight-color: transparent;
}
:where(.ui-kit button:not([data-slot])) {
  color: inherit;
}
:where(.ui-kit a:not([data-slot])) {
  color: inherit;
  text-decoration: none;
}
/* Universal focus fallback: an accent ring with offset on every keyboard
   target. :where() keeps specificity at zero, so the per-component
   focus-visible rules throughout the design system still win when set. */
:where(.ui-kit :is(button, a, input, select, [tabindex]):focus-visible) {
  outline: var(--focus-ring-width) solid var(--focus-ring);
  outline-offset: var(--focus-ring-offset);
}

@layer base {
  * {
    border-color: var(--border);
    outline-color: color-mix(in srgb, var(--ring) 50%, transparent);
  }
  body {
    color: var(--foreground);
    background-color: var(--background);
  }
  button:not(:disabled),
  [role="button"]:not(:disabled) {
    cursor: pointer;
  }
  html {
    font-family: var(--font-geist-sans), Arial, Helvetica, sans-serif;
  }
}

/* Kinetic skin for the hand-built reusable controls: infinite logo marquee,
   loading buttons, auth cards, pickers, popovers, switches, and tooltips. */

.infinite-logo-carousel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
}
.infinite-logo-viewport {
  min-width: 0;
  padding: 8px 0;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
  mask-image: linear-gradient(to right, transparent, #000 7%, #000 93%, transparent);
}
.infinite-logo-track {
  display: flex;
  width: max-content;
  will-change: transform;
  animation: infinite-logo-scroll var(--logo-carousel-duration, 32s) linear infinite;
}
.infinite-logo-carousel.moves-right .infinite-logo-track {
  animation-direction: reverse;
}
.infinite-logo-carousel.is-paused .infinite-logo-track,
.infinite-logo-carousel.pauses-on-interaction .infinite-logo-viewport:hover .infinite-logo-track,
.infinite-logo-carousel.pauses-on-interaction .infinite-logo-viewport:focus-within .infinite-logo-track {
  animation-play-state: paused;
}
@keyframes infinite-logo-scroll {
  to {
    transform: translate3d(-50%, 0, 0);
  }
}
.infinite-logo-group {
  display: flex;
  flex: none;
  align-items: center;
  gap: 10px;
  padding-inline: 5px;
}
.infinite-logo-item {
  width: 142px;
  min-height: 66px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 13px;
  border: 1px solid var(--border-soft);
  border-radius: var(--kinetic-radius-control);
  color: var(--text-soft);
  background: linear-gradient(145deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
  text-decoration: none;
  transition:
    color 180ms ease,
    border-color 180ms ease,
    transform 180ms ease,
    box-shadow 180ms ease;
}
.infinite-logo-item:hover,
.infinite-logo-item:focus-visible {
  border-color: color-mix(in srgb, var(--logo-brand, var(--accent)) 48%, var(--border));
  color: var(--logo-brand, var(--accent));
  box-shadow:
    var(--shadow-control),
    0 5px 14px color-mix(in srgb, var(--logo-brand, var(--accent)) 14%, transparent);
  outline: none;
  transform: translateY(-2px);
}
.infinite-logo-mark {
  width: 34px;
  height: 34px;
  flex: none;
  display: grid;
  place-items: center;
  border: 1px solid var(--border-soft);
  border-radius: var(--kinetic-radius-control);
  color: var(--text-soft);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
  transition: color 180ms ease;
}
.infinite-logo-item:hover .infinite-logo-mark,
.infinite-logo-item:focus-visible .infinite-logo-mark {
  color: var(--logo-brand, var(--accent));
}
.infinite-logo-mark :is(svg, img) {
  width: 18px;
  height: 18px;
}
.infinite-logo-mark svg {
  fill: currentColor;
}
.infinite-logo-mark img {
  object-fit: contain;
}
.infinite-logo-mark > span {
  font-family: var(--font-geist-mono), monospace;
  font-size: var(--text-2xs);
  font-weight: 700;
}
.infinite-logo-name {
  overflow: hidden;
  font-size: var(--text-2xs);
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.infinite-logo-pause {
  min-width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  color: var(--text-muted);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
  cursor: pointer;
}
.infinite-logo-pause:hover,
.infinite-logo-pause:focus-visible,
.infinite-logo-pause[aria-pressed="true"] {
  color: var(--accent);
  outline: none;
  box-shadow:
    var(--shadow-control),
    0 0 0 3px var(--accent-soft);
}
.infinite-logo-pause-icon {
  display: grid;
  place-items: center;
  line-height: 0;
}
.infinite-logo-pause-icon > svg {
  width: 15px;
  height: 15px;
  stroke-width: 2.25;
}
.infinite-logo-pause-icon.is-play {
  transform: translateX(1px);
}
.infinite-logo-pause-label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  clip-path: inset(50%);
}
.infinite-logo-pause:focus-visible {
  width: auto;
  grid-auto-flow: column;
  gap: 7px;
  padding-inline: 11px;
}
.infinite-logo-pause:focus-visible .infinite-logo-pause-label {
  position: static;
  width: auto;
  height: auto;
  overflow: visible;
  clip: auto;
  clip-path: none;
  font-size: 11px;
}
.loading-button {
  position: relative;
}
.loading-button-content,
.loading-button-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: inherit;
}
.loading-button-status {
  position: absolute;
  inset: 0;
  padding: inherit;
  pointer-events: none;
}
.loading-button[data-loading] .loading-button-content {
  visibility: hidden;
}
.loading-button-spinner {
  flex: none;
  animation: loading-button-spin 720ms linear infinite;
}
@keyframes loading-button-spin {
  to {
    transform: rotate(360deg);
  }
}
.loading-button:disabled {
  cursor: wait;
}
.button.loading-button:disabled,
.auth-submit:disabled,
.send-button.loading-button:disabled {
  opacity: 0.78;
  filter: saturate(0.82);
}
.auth-card-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--density-grid-gap, 16px);
  margin-bottom: var(--density-grid-gap, 16px);
}
.forgot-password-card {
  min-width: 0;
  width: 100%;
  margin: 0;
}
.forgot-password-form {
  padding-top: 16px;
}
.forgot-password-otp {
  width: max-content;
  max-width: 100%;
}
.forgot-password-otp [data-slot="input-otp-slot"] {
  width: 38px;
  height: 40px;
  font-family: var(--font-geist-mono), monospace;
  font-size: var(--text-md);
  font-weight: 650;
}
.forgot-password-field-note {
  margin-top: -1px;
  color: var(--text-muted);
  font-size: var(--text-2xs);
}
.forgot-password-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 9px;
}
.forgot-password-actions .auth-submit {
  min-width: 164px;
}
.forgot-password-footer {
  margin-top: 16px;
}
.forgot-password-success {
  display: grid;
  justify-items: center;
  gap: 9px;
  padding: 26px 10px 4px;
  text-align: center;
}
.forgot-password-success-icon {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--success) 46%, var(--border));
  border-radius: 50%;
  color: var(--success);
  background: color-mix(in srgb, var(--success) 12%, var(--surface-inset));
  box-shadow: var(--shadow-control);
}
.forgot-password-success strong {
  font-size: var(--text-lg);
}
.forgot-password-success p {
  max-width: 360px;
  margin: 0 0 5px;
  color: var(--text-muted);
  font-size: var(--text-xs);
  line-height: 1.5;
}
.forgot-password-success .auth-submit {
  width: min(100%, 250px);
}
.auth-card {
  min-width: 0;
  padding: var(--density-panel-padding, 24px);
}
.auth-card-header {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--border-soft);
}
.auth-brand-mark {
  width: 38px;
  height: 38px;
  flex: none;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 45%, var(--border));
  border-radius: var(--kinetic-radius-control);
  color: var(--accent);
  background: var(--accent-soft);
  box-shadow:
    var(--shadow-control),
    0 6px 15px var(--accent-glow);
}
.auth-card-header > div {
  min-width: 0;
}
.auth-card-header span:not(.auth-brand-mark) {
  color: var(--accent);
  font-size: var(--text-2xs);
  font-weight: 750;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.auth-card-header h3 {
  margin: 4px 0 3px;
  font-family: var(--font-dot-gothic), sans-serif;
  font-size: 21px;
  font-weight: 400;
}
.auth-card-header p {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--text-2xs);
}
.auth-form {
  display: grid;
  gap: 13px;
  padding-top: 18px;
}
.auth-field {
  min-width: 0;
  display: grid;
  gap: 7px;
}
.auth-field > label {
  color: var(--text-soft);
  font-size: var(--text-xs);
  font-weight: 650;
}
.auth-input-shell {
  height: 40px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 11px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  color: var(--text-muted);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease;
}
.auth-input-shell:focus-within {
  border-color: color-mix(in srgb, var(--accent) 58%, var(--border));
  color: var(--accent);
  box-shadow:
    var(--shadow-inset),
    0 0 0 3px var(--accent-soft);
}
.auth-input-shell input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  color: var(--text);
  background: transparent;
  font: inherit;
  font-size: var(--text-md);
}
.auth-input-shell input::placeholder {
  color: var(--text-muted);
  opacity: 0.72;
}
.auth-password-toggle {
  width: 27px;
  height: 27px;
  flex: none;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: var(--kinetic-radius-sm);
  color: var(--text-muted);
  background: transparent;
  cursor: pointer;
}
.auth-password-toggle:hover,
.auth-password-toggle:focus-visible {
  color: var(--accent);
  background: var(--accent-soft);
  outline: none;
}
.auth-options {
  min-height: 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.auth-check {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--text-muted);
  font-size: var(--text-2xs);
  cursor: pointer;
}
.auth-check input {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 1;
  width: 16px;
  height: 16px;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}
.auth-check-control {
  position: relative;
  width: 16px;
  height: 16px;
  flex: none;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-xs);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.auth-check-control::after {
  content: "";
  position: absolute;
  left: 5px;
  top: 2px;
  width: 4px;
  height: 7px;
  border: solid var(--action-foreground);
  border-width: 0 2px 2px 0;
  opacity: 0;
  transform: rotate(45deg) scale(0.7);
  transition:
    opacity 120ms ease,
    transform 160ms ease;
}
.auth-check input:checked + .auth-check-control {
  border-color: color-mix(in srgb, var(--accent) 58%, var(--border));
  background: linear-gradient(180deg, var(--action-top), var(--action-bottom));
  box-shadow:
    0 3px 7px var(--accent-glow),
    inset 0 1px 0 rgba(255, 255, 255, 0.3);
}
.auth-check input:checked + .auth-check-control::after {
  opacity: 1;
  transform: rotate(45deg) scale(1);
}
.auth-check input:focus-visible + .auth-check-control {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.auth-text-button {
  padding: 0;
  border: 0;
  color: var(--accent);
  background: transparent;
  font: inherit;
  font-size: var(--text-xs);
  font-weight: 650;
  cursor: pointer;
}
.auth-text-button:hover,
.auth-text-button:focus-visible {
  text-decoration: underline;
  text-underline-offset: 3px;
  outline: none;
}
.auth-error {
  margin: -4px 0 0;
  color: var(--destructive);
  font-size: var(--text-xs);
}
.auth-submit {
  height: var(--kinetic-control-height);
  min-height: var(--kinetic-control-height);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding-inline: 15px;
  border: 1px solid rgba(255, 130, 76, 0.42);
  border-radius: var(--kinetic-radius-control);
  color: var(--action-foreground);
  background: linear-gradient(180deg, var(--action-top), var(--action-bottom));
  box-shadow:
    0 6px 13px var(--accent-glow),
    inset 0 1px 0 rgba(255, 255, 255, 0.3);
  font: inherit;
  font-size: var(--text-sm);
  font-weight: 750;
  cursor: pointer;
  transition:
    filter 150ms ease,
    transform 100ms ease,
    box-shadow 100ms ease;
}
.auth-submit:hover,
.auth-submit:focus-visible {
  filter: brightness(1.08);
  outline: none;
  box-shadow:
    0 7px 16px var(--accent-glow),
    inset 0 1px 0 rgba(255, 255, 255, 0.35),
    0 0 0 3px var(--accent-soft);
}
.auth-submit:active {
  transform: translateY(1px);
  box-shadow: var(--shadow-inset);
}
.auth-card-footer {
  display: flex;
  justify-content: center;
  gap: 5px;
  margin-top: 17px;
  padding-top: 14px;
  border-top: 1px solid var(--border-soft);
  color: var(--text-muted);
  font-size: var(--text-2xs);
}
.demo-panel {
  min-height: 285px;
}
.button-demo-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 9px;
}
.button {
  height: var(--kinetic-control-height);
  min-height: var(--kinetic-control-height);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 15px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  font-size: var(--text-sm);
  font-weight: 650;
  cursor: pointer;
  transition:
    transform 0.12s ease,
    filter 0.12s ease,
    box-shadow 0.12s ease;
}
.button:hover {
  filter: brightness(1.08);
}
.button:active {
  transform: translateY(2px);
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.36);
}
.button-primary {
  color: var(--action-foreground);
  border-color: rgba(255, 130, 76, 0.43);
  background: linear-gradient(180deg, var(--action-top), var(--action-bottom));
  box-shadow:
    0 7px 16px var(--accent-glow),
    inset 0 1px 0 rgba(255, 255, 255, 0.37),
    inset 0 -1px 0 rgba(101, 28, 3, 0.56);
  text-shadow: 0 1px 1px rgba(0, 0, 0, 0.32);
}
.button-secondary {
  color: var(--text);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
}
.button-ghost {
  color: var(--text-soft);
  border-color: transparent;
  background: transparent;
}
.button-ghost:hover {
  border-color: var(--border);
  background: var(--surface-flat);
}
.button-danger {
  color: #fff6f6;
  border-color: color-mix(in srgb, var(--danger) 46%, transparent);
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--danger) 90%, white 10%),
    color-mix(in srgb, var(--danger) 72%, black 28%)
  );
  box-shadow:
    0 6px 14px color-mix(in srgb, var(--danger) 20%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.28);
}
.button.compact {
  height: var(--kinetic-control-height-compact);
  min-height: var(--kinetic-control-height-compact);
  padding-inline: 12px;
  font-size: var(--text-xs);
}
.button.full-width {
  width: 100%;
}
.icon-button {
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--kinetic-radius-control);
  color: var(--text-soft);
  background: transparent;
  cursor: pointer;
  transition: 0.15s ease;
}
.icon-button:hover {
  color: var(--text);
  border-color: var(--border);
  background: var(--surface-hover);
}
.icon-button.raised {
  border-color: var(--border);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
}
.icon-button.raised:active {
  transform: translateY(2px);
  box-shadow: var(--shadow-inset);
}
.button-group {
  width: max-content;
  max-width: 100%;
  display: flex;
  margin-top: 25px;
  padding: 3px;
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.button-group button {
  min-height: var(--kinetic-control-height-compact);
  padding: 0 12px;
  border: 0;
  border-radius: var(--kinetic-radius-sm);
  color: var(--text-muted);
  background: transparent;
  white-space: nowrap;
  cursor: pointer;
  font-size: var(--text-xs);
}
.button-group button.active {
  color: var(--text);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
}

.field-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 13px;
}
.field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}
.field.full {
  grid-column: 1 / -1;
}
.field > span {
  color: var(--text-soft);
  font-size: var(--text-2xs);
  font-weight: 600;
}
.input-shell,
.select-shell {
  min-width: 0;
  height: 38px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 11px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  color: var(--text-muted);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
  transition:
    border-color 0.15s,
    box-shadow 0.15s;
}
.input-shell:focus-within,
.select-shell:focus-within {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--border));
  box-shadow:
    var(--shadow-inset),
    0 0 0 3px var(--accent-soft);
}
.input-shell input,
.select-shell select {
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  color: var(--text);
  background: transparent;
  font-size: var(--text-md);
}
.input-shell input::placeholder {
  color: var(--text-muted);
}
.select-shell {
  position: relative;
}
.select-shell select {
  appearance: none;
  cursor: pointer;
}
.select-shell svg {
  position: absolute;
  right: 10px;
  pointer-events: none;
}
.custom-control {
  position: relative;
}
.custom-control.is-open {
  z-index: 25;
}
.custom-trigger {
  width: 100%;
  min-width: 0;
  height: 38px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 10px 0 12px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  color: var(--text);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
  cursor: pointer;
  text-align: left;
  transition:
    transform 120ms ease,
    border-color 0.15s,
    box-shadow 0.15s,
    background 0.15s;
}
.custom-trigger:hover {
  background: color-mix(in srgb, var(--surface-inset) 88%, var(--surface-top));
}
.custom-trigger:active {
  transform: translateY(1px);
}
.custom-trigger:focus-visible,
.custom-trigger[aria-expanded="true"] {
  outline: 0;
  border-color: color-mix(in srgb, var(--accent) 58%, var(--border));
  box-shadow:
    var(--shadow-inset),
    0 0 0 3px var(--accent-soft);
}
.custom-trigger > span {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  color: var(--text);
  font-size: var(--text-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.custom-trigger > svg {
  flex: 0 0 auto;
  color: var(--text-muted);
}
.theme-choice-icon {
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-sm);
  box-shadow: var(--shadow-inset);
}
.theme-choice-icon.dark,
.option-swatch.dark {
  color: #dad8d0;
  background: linear-gradient(145deg, #2b2e31, #0b0d0f);
}
.theme-choice-icon.light,
.option-swatch.light {
  color: #b84b20;
  background: linear-gradient(145deg, #fffefa, #d4d1c8);
}
.theme-choice-icon.system,
.option-swatch.system {
  color: var(--text-soft);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
}
.trigger-chevron {
  transition: transform 0.16s ease;
}
.custom-trigger[aria-expanded="true"] .trigger-chevron {
  color: var(--accent);
  transform: rotate(180deg);
}
.control-popover {
  position: absolute;
  top: calc(100% + 7px);
  left: 0;
  z-index: 40;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-menu);
  color: var(--text);
  background: linear-gradient(155deg, var(--surface-top), var(--surface-mid) 55%, var(--surface-bottom));
  box-shadow:
    0 22px 46px rgba(0, 0, 0, 0.36),
    inset 0 1px 0 var(--edge-light);
}
.control-popover.align-right {
  right: 0;
  left: auto;
}
.date-popover {
  width: 278px;
  padding: 10px;
}
.picker-heading {
  height: 36px;
  display: grid;
  grid-template-columns: 30px 1fr 30px;
  align-items: center;
  margin-bottom: 5px;
}
.picker-heading strong {
  font-family: var(--font-dot-gothic), sans-serif;
  font-size: 13px;
  font-weight: 400;
  text-align: center;
}
.picker-heading-selects {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 67px;
  gap: 4px;
  padding: 0 4px;
}
.picker-heading-selects select {
  min-width: 0;
  height: 28px;
  padding: 0 5px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-sm);
  outline: 0;
  color: var(--text);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
  cursor: pointer;
  font-family: var(--font-dot-gothic), sans-serif;
  font-size: var(--text-md);
}
.picker-heading-selects select:focus-visible {
  border-color: color-mix(in srgb, var(--accent) 58%, var(--border));
  box-shadow:
    var(--shadow-inset),
    0 0 0 2px var(--accent-soft);
}
.picker-heading button,
.picker-footer button,
.time-step button {
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--kinetic-radius-sm);
  color: var(--text-muted);
  background: transparent;
  cursor: pointer;
}
.picker-heading button {
  width: 29px;
  height: 29px;
}
.picker-heading button:hover,
.time-step button:hover {
  color: var(--accent);
  border-color: var(--border);
  background: var(--surface-hover);
  box-shadow: var(--shadow-control);
}
.picker-heading button:active,
.time-step button:active {
  transform: translateY(1px) scale(0.95);
}
.picker-footer button:active {
  transform: translateY(1px);
}
.picker-weekdays,
.picker-days {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 3px;
}
.picker-weekdays {
  margin-bottom: 4px;
}
.picker-weekdays span {
  padding: 6px 0;
  color: var(--text-muted);
  font-size: var(--text-2xs);
  font-weight: 750;
  text-align: center;
}
.picker-days button {
  aspect-ratio: 1;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--kinetic-radius-sm);
  color: var(--text-soft);
  background: transparent;
  cursor: pointer;
  font-size: var(--text-2xs);
  transition:
    transform 120ms ease,
    border-color 120ms ease,
    background 120ms ease,
    box-shadow 120ms ease;
}
.picker-days button:hover {
  color: var(--text);
  border-color: var(--border);
  background: var(--surface-hover);
}
.picker-days button:active:not(.selected) {
  transform: scale(0.96);
}
.picker-days button.muted {
  color: color-mix(in srgb, var(--text-muted) 48%, transparent);
}
.picker-days button.selected {
  color: var(--action-foreground);
  border-color: rgba(255, 144, 93, 0.48);
  background: linear-gradient(180deg, var(--action-top), var(--action-bottom));
  box-shadow:
    0 4px 9px var(--accent-glow),
    inset 0 1px 0 rgba(255, 255, 255, 0.34);
}
.picker-footer {
  display: flex;
  justify-content: space-between;
  margin: 8px -2px -2px;
  padding-top: 8px;
  border-top: 1px solid var(--border-soft);
}
.picker-footer button {
  min-height: 28px;
  padding: 0 9px;
  color: var(--accent);
  font-size: var(--text-xs);
}
.picker-footer button:hover {
  background: var(--accent-soft);
}
.time-popover {
  width: 258px;
  padding: 14px;
}
.date-time-popover {
  width: min(570px, calc(100vw - 28px));
  padding: 14px;
}
.date-time-popover-heading {
  display: grid;
  gap: 3px;
  padding-bottom: 11px;
  border-bottom: 1px solid var(--border-soft);
}
.date-time-popover-heading p {
  margin: 0;
  color: var(--text-muted);
  font-size: var(--text-2xs);
}
.date-time-picker-embedded {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(0, 1fr);
  gap: 14px;
  margin-top: 13px;
}
.date-time-picker-embedded > .custom-control {
  display: contents;
}
.date-time-picker-embedded > .custom-control > .control-popover {
  position: static;
  inset: auto;
  width: auto;
  padding: 0;
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.date-time-picker-footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--border-soft);
}
.date-time-picker-footer .button {
  min-height: 34px;
}
.popover-kicker {
  display: block;
  color: var(--accent);
  font-size: var(--text-2xs);
  font-weight: 750;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.time-format-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.time-format-toggle,
.period-toggle {
  display: flex;
  padding: 3px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-sm);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.time-format-toggle button,
.period-toggle button {
  min-width: 32px;
  height: 23px;
  padding: 0 7px;
  border: 0;
  border-radius: var(--kinetic-radius-xs);
  color: var(--text-muted);
  background: transparent;
  cursor: pointer;
  font-size: var(--text-xs);
  font-weight: 700;
}
.time-format-toggle button.selected,
.period-toggle button.selected {
  color: var(--text);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
}
.time-format-toggle button:active,
.period-toggle button:active {
  transform: translateY(1px) scale(0.98);
}
.time-steppers {
  display: grid;
  grid-template-columns: 1fr 16px 1fr;
  align-items: center;
  gap: 5px;
  margin: 11px 0;
}
.time-steppers > b {
  color: var(--text-muted);
  font-family: var(--font-dot-gothic), monospace;
  font-size: 24px;
  font-weight: 400;
  text-align: center;
}
.time-step {
  display: grid;
  grid-template-rows: 25px 40px 25px 15px;
  place-items: center;
  padding: 7px 6px 4px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.time-step button {
  width: 28px;
  height: 23px;
}
.time-step input {
  width: 100%;
  min-width: 0;
  height: 36px;
  padding: 0;
  border: 0;
  outline: 0;
  color: var(--text);
  background: transparent;
  caret-color: var(--accent);
  font-family: var(--font-dot-gothic), monospace;
  font-size: 24px;
  font-weight: 400;
  text-align: center;
}
.time-step input:focus-visible {
  border-radius: var(--kinetic-radius-xs);
  background: var(--accent-soft);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 38%, transparent);
}
.time-step input[data-auto-focused] {
  background: transparent;
  box-shadow: none;
}
.time-step input::selection {
  color: white;
  background: var(--accent);
}
.time-step small {
  color: var(--text-muted);
  font-size: 10px;
  text-transform: uppercase;
}
.time-presets {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
}
.period-toggle {
  width: max-content;
  margin: -3px auto 9px;
}
.period-toggle button {
  min-width: 62px;
}
.time-presets.twelve-hour {
  grid-template-columns: repeat(2, 1fr);
}
.time-presets button {
  min-height: 28px;
  padding: 0;
  border: 1px solid var(--border-soft);
  border-radius: var(--kinetic-radius-sm);
  color: var(--text-muted);
  background: var(--surface-flat);
  cursor: pointer;
  font-family: var(--font-geist-mono), monospace;
  font-size: var(--text-xs);
}
.time-presets button:hover,
.time-presets button.selected {
  color: var(--accent);
  border-color: color-mix(in srgb, var(--accent) 42%, var(--border));
  background: var(--accent-soft);
}
.time-presets button:active:not(.selected) {
  transform: translateY(1px) scale(0.98);
}
.picker-done {
  width: 100%;
  height: var(--kinetic-control-height);
  min-height: var(--kinetic-control-height);
  padding-inline: 15px;
  margin-top: 10px;
  border: 1px solid rgba(255, 130, 76, 0.4);
  border-radius: var(--kinetic-radius-control);
  color: var(--action-foreground);
  background: linear-gradient(180deg, var(--action-top), var(--action-bottom));
  box-shadow: var(--shadow-control);
  cursor: pointer;
  font-size: var(--button-label-size, var(--text-sm));
  font-weight: 700;
  transition:
    transform 120ms ease,
    box-shadow 120ms ease;
}
.picker-done:active {
  transform: translateY(1px);
  box-shadow: var(--shadow-inset);
}
.option-popover {
  width: 100%;
  padding: 6px;
}
.option-popover > button,
.combobox-popover > button {
  width: 100%;
  min-height: 46px;
  display: flex;
  align-items: center;
  gap: 10px;
