  box-shadow: var(--shadow-inset);
}
.ui-kit [data-slot="data-table"] .data-table-surface {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-menu);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.ui-kit [data-slot="data-table"] .data-table-surface [data-slot="table-container"] {
  overflow-x: auto;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.ui-kit :is([data-slot="table-head"], [data-slot="table-footer"]) {
  color: var(--text-soft);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-flat));
  box-shadow:
    inset 0 -1px 0 var(--border-soft),
    inset 0 1px 0 var(--edge-light);
}
.ui-kit [data-slot="table-row"] {
  border-color: var(--border-soft);
}
.ui-kit [data-slot="table-row"]:hover {
  background: var(--chart-hover);
}
.ui-kit [data-slot="table-caption"] {
  color: var(--text-muted);
}
.ui-kit [data-slot="breadcrumb-link"] {
  display: inline-flex;
  min-height: 30px;
  align-items: center;
  padding: 0 9px;
  border: 1px solid transparent;
  border-radius: var(--kinetic-radius-sm);
  color: var(--text-muted);
}
.ui-kit [data-slot="pagination-link"] {
  border-radius: var(--kinetic-radius-sm);
  color: var(--text-muted);
}
.ui-kit [data-slot="breadcrumb-link"]:hover,
.ui-kit [data-slot="breadcrumb-link"]:focus-visible {
  border-color: var(--border);
  color: var(--text);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
}
.ui-kit [data-slot="pagination-link"]:hover {
  color: var(--text);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
}
.ui-kit [data-slot="pagination-link"][data-active="true"] {
  border-color: color-mix(in srgb, var(--accent) 58%, var(--border));
  color: var(--action-foreground);
  background: linear-gradient(180deg, var(--action-top), var(--action-bottom));
  box-shadow:
    0 4px 9px var(--accent-glow),
    inset 0 1px 0 rgba(255, 255, 255, 0.34);
}
.ui-kit [data-slot="breadcrumb-page"] {
  color: var(--text);
}
.ui-kit :is([data-slot="breadcrumb-separator"], [data-slot="breadcrumb-ellipsis"]) {
  color: var(--text-muted);
}
.ui-kit [data-slot="resizable-handle"] {
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-pill);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
}
.ui-kit [data-slot="resizable-handle"]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.ui-kit [data-slot="scroll-area-scrollbar"] {
  background: color-mix(in srgb, var(--surface-inset) 72%, transparent);
}
.ui-kit [data-slot="scroll-area-thumb"] {
  border-radius: var(--kinetic-radius-pill);
  border: 1px solid var(--border);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
}
.ui-kit [data-slot="sidebar"] {
  border-color: var(--border);
  color: var(--text);
  background: linear-gradient(165deg, var(--surface-top), var(--surface-mid) 36%, var(--surface-bottom));
  box-shadow: var(--shadow-raised);
}
.ui-kit :is([data-slot="sidebar-input"], [data-slot="command-input"], [data-slot="questionnaire-input"]) {
  color: var(--text);
  caret-color: var(--accent);
}
.ui-kit [data-slot="sidebar-group-label"] {
  color: var(--text-muted);
  font-size: var(--text-2xs);
  font-weight: 750;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.ui-kit :is([data-slot="sidebar-menu-button"], [data-slot="sidebar-menu-sub-button"]) {
  border: 1px solid transparent;
  border-radius: var(--kinetic-radius-sm);
  color: var(--text-soft);
}
.ui-kit
  :is([data-slot="sidebar-menu-button"], [data-slot="sidebar-menu-sub-button"]):is(
    [data-active="true"],
    [aria-current="page"]
  ) {
  border-color: var(--border);
  color: var(--text);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
}
.ui-kit [data-slot="sidebar-menu-badge"] {
  border: 1px solid color-mix(in srgb, var(--accent) 34%, var(--border));
  border-radius: var(--kinetic-radius-pill);
  color: var(--accent);
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--accent-soft) 78%, var(--surface-top)),
    var(--accent-soft)
  );
  box-shadow: var(--shadow-control);
}
.ui-kit
  :is([data-slot="carousel-previous"], [data-slot="carousel-next"], [data-slot="message-scroller-button"]) {
  border-color: var(--border);
  color: var(--text-soft);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
}
.ui-kit [data-slot="questionnaire-progress"] {
  border: 1px solid var(--border);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.ui-kit [data-slot="questionnaire-choice"]:is([data-checked], [aria-checked="true"]) {
  border-color: color-mix(in srgb, var(--accent) 48%, var(--border));
  background: color-mix(in srgb, var(--accent-soft) 62%, var(--surface-flat));
  box-shadow:
    var(--shadow-control),
    0 0 0 2px var(--accent-soft);
}
.ui-kit [data-slot="spinner"] {
  color: var(--accent);
}

/* Portalled surfaces (dialogs, sheets, drawers, popovers, menus, toasts)
   and the custom modal/command overlay layers. These live outside the
   .ui-kit wrapper, so they use semantic Kinetic colors directly. */

/* Portalled surfaces live outside .ui-kit, so they use semantic Kinetic colors. */
:is(
  [data-slot="popover-content"],
  [data-slot="select-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"],
  [data-slot="combobox-content"],
  [data-slot="navigation-menu-content"],
  [data-slot="navigation-menu-viewport"],
  [data-slot="dialog-content"],
  [data-slot="alert-dialog-content"],
  [data-slot="sheet-content"],
  [data-slot="drawer-content"],
  [data-slot="hover-card-content"]
) {
  border-radius: var(--kinetic-radius-menu);
  border: 1px solid color-mix(in srgb, var(--border) 78%, var(--foreground) 12%);
  color: var(--popover-foreground);
  background: linear-gradient(
    155deg,
    color-mix(in srgb, var(--popover) 93%, white 7%),
    var(--popover) 48%,
    var(--secondary)
  );
  box-shadow: var(--shadow-overlay);
}
:is(
  [data-slot="dialog-overlay"],
  [data-slot="alert-dialog-overlay"],
  [data-slot="sheet-overlay"],
  [data-slot="drawer-overlay"]
) {
  background: rgba(9, 10, 11, 0.58);
  backdrop-filter: blur(8px) saturate(0.78);
}
:is([data-slot="dialog-content"], [data-slot="alert-dialog-content"]) {
  border-radius: var(--kinetic-radius-panel);
}
[data-slot="sheet-content"] {
  border-left-width: 1px;
  box-shadow:
    -24px 0 58px rgba(0, 0, 0, 0.34),
    inset 1px 0 0 rgba(255, 255, 255, 0.28);
}
@media (min-width: 981px) {
  [data-slot="sheet-content"][data-side="right"] {
    top: 12px;
    right: 12px;
    bottom: 12px;
    height: calc(100% - 24px);
    border-radius: var(--kinetic-radius-panel);
  }
}
[data-slot="drawer-content"] {
  border-radius: var(--kinetic-radius-panel) var(--kinetic-radius-panel) 0 0;
  box-shadow:
    0 -24px 58px rgba(0, 0, 0, 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.38);
}
[data-slot="drawer-content"][data-vaul-drawer-direction="bottom"] {
  height: auto;
  min-height: 0;
  max-height: min(420px, calc(100svh - 24px));
  overflow-y: auto;
}
[data-slot="drawer-content"][data-vaul-drawer-direction="bottom"] [data-slot="drawer-footer"] {
  margin-top: 18px;
}
:is(
    [data-slot="dialog-content"],
    [data-slot="alert-dialog-content"],
    [data-slot="sheet-content"],
    [data-slot="drawer-content"]
  )
  :is(
    [data-slot="dialog-title"],
    [data-slot="alert-dialog-title"],
    [data-slot="sheet-title"],
    [data-slot="drawer-title"]
  ) {
  color: var(--foreground);
  font-family: var(--font-dot-gothic), sans-serif;
  font-size: 18px;
  font-weight: 400;
}
:is(
    [data-slot="dialog-content"],
    [data-slot="alert-dialog-content"],
    [data-slot="sheet-content"],
    [data-slot="drawer-content"]
  )
  :is(
    [data-slot="dialog-description"],
    [data-slot="alert-dialog-description"],
    [data-slot="sheet-description"],
    [data-slot="drawer-description"]
  ) {
  color: var(--muted-foreground);
  font-size: 13px;
}
:is([data-slot="dialog-footer"], [data-slot="alert-dialog-footer"]) {
  border-color: var(--border);
  background: color-mix(in srgb, var(--secondary) 55%, var(--popover));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.22);
}
[data-slot="alert-dialog-media"] {
  border: 1px solid color-mix(in srgb, var(--destructive) 50%, var(--border));
  color: var(--destructive);
  background: color-mix(in srgb, var(--destructive) 12%, var(--secondary));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.28),
    0 5px 12px color-mix(in srgb, var(--destructive) 18%, transparent);
}
[data-slot="drawer-content"] > div:first-child {
  border: 1px solid color-mix(in srgb, var(--border) 72%, transparent);
  background: color-mix(in srgb, var(--muted-foreground) 52%, transparent);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.26);
}

/* Dialog, sheet, and drawer actions use the same full-size tactile target as
   ordinary Kinetic buttons. This intentionally normalizes footer buttons
   even when a generated shadcn example supplied a compact `size="sm"`.
   Icon buttons remain compact/square by design. */
:is(
    [data-slot="dialog-footer"],
    [data-slot="alert-dialog-footer"],
    [data-slot="sheet-footer"],
    [data-slot="drawer-footer"]
  )
  button:not([data-size^="icon"]) {
  height: var(--kinetic-control-height);
  min-height: var(--kinetic-control-height);
  padding-inline: 15px;
  border-radius: var(--kinetic-radius-control);
  font-size: var(--button-label-size, var(--text-sm));
}

/* Drawer quick actions are action buttons too, rather than compact menu
   items, so they share the same dimensions as the drawer footer action. */
.drawer-action-grid [data-slot="button"]:not([data-size^="icon"]) {
  height: var(--kinetic-control-height);
  min-height: var(--kinetic-control-height);
  padding-inline: 15px;
  border-radius: var(--kinetic-radius-control);
  font-size: var(--button-label-size, var(--text-sm));
}

:is(
    [data-slot="dialog-content"],
    [data-slot="alert-dialog-content"],
    [data-slot="sheet-content"],
    [data-slot="drawer-content"]
  )
  :is([data-slot="button"], [data-slot="alert-dialog-action"], [data-slot="alert-dialog-cancel"]) {
  height: var(--kinetic-control-height);
  min-height: var(--kinetic-control-height);
  padding-inline: 15px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  color: var(--foreground);
  background: linear-gradient(180deg, color-mix(in srgb, var(--secondary) 82%, white 18%), var(--secondary));
  box-shadow:
    0 5px 12px rgba(0, 0, 0, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.46),
    inset 0 -1px 0 color-mix(in srgb, var(--foreground) 14%, transparent);
  font-size: 13px;
  font-weight: 650;
}
:is(
    [data-slot="dialog-content"],
    [data-slot="alert-dialog-content"],
    [data-slot="sheet-content"],
    [data-slot="drawer-content"]
  )
  [data-slot="button"][data-size="sm"] {
  height: var(--kinetic-control-height-compact);
  min-height: var(--kinetic-control-height-compact);
  padding-inline: 12px;
}
:is(
    [data-slot="dialog-content"],
    [data-slot="alert-dialog-content"],
    [data-slot="sheet-content"],
    [data-slot="drawer-content"]
  )
  [data-slot="button"][data-variant="default"],
[data-slot="alert-dialog-content"] [data-slot="alert-dialog-action"] {
  border-color: color-mix(in srgb, var(--primary) 70%, var(--border));
  color: var(--primary-foreground);
  background: linear-gradient(180deg, color-mix(in srgb, var(--primary) 78%, white 22%), var(--primary));
  box-shadow:
    0 7px 16px color-mix(in srgb, var(--primary) 30%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    inset 0 -1px 0 rgba(55, 15, 2, 0.4);
}
[data-slot="alert-dialog-content"] [data-slot="alert-dialog-action"][data-variant="destructive"] {
  border-color: color-mix(in srgb, var(--destructive) 70%, var(--border));
  color: white;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--destructive) 76%, white 24%),
    var(--destructive)
  );
  box-shadow:
    0 7px 16px color-mix(in srgb, var(--destructive) 26%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.34),
    inset 0 -1px 0 rgba(54, 8, 8, 0.38);
}
:is(
    [data-slot="dialog-content"],
    [data-slot="alert-dialog-content"],
    [data-slot="sheet-content"],
    [data-slot="drawer-content"]
  )
  [data-slot="button"][data-variant="ghost"] {
  min-height: 32px;
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}
:is(
    [data-slot="dialog-content"],
    [data-slot="alert-dialog-content"],
    [data-slot="sheet-content"],
    [data-slot="drawer-content"]
  )
  [data-slot="input"] {
  height: 40px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  color: var(--foreground);
  background: color-mix(in srgb, var(--secondary) 68%, var(--popover));
  box-shadow:
    inset 0 2px 5px rgba(0, 0, 0, 0.2),
    inset 0 -1px 0 rgba(255, 255, 255, 0.32);
  font-size: 14px;
}
.portal-form-field {
  display: grid;
  gap: 8px;
}
.portal-form-field [data-slot="label"] {
  font-size: 12px;
}
.portal-setting-list {
  display: grid;
  gap: 8px;
  padding: 0 16px;
}
.portal-setting-row {
  min-height: 62px;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  background: color-mix(in srgb, var(--secondary) 58%, var(--popover));
  box-shadow:
    inset 0 2px 5px rgba(0, 0, 0, 0.16),
    inset 0 -1px 0 rgba(255, 255, 255, 0.28);
}
.portal-setting-row > span {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.portal-setting-row strong {
  font-size: 13px;
}
.portal-setting-row small {
  color: var(--muted-foreground);
  font-size: 11px;
}
.portal-setting-row [data-slot="switch"] {
  width: 39px;
  height: 22px;
  padding: 1px;
  border-color: var(--border);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.22);
}
.portal-setting-row [data-slot="switch-thumb"] {
  width: 18px;
  height: 18px;
}
.drawer-action-grid {
  width: min(560px, calc(100% - 32px));
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-inline: auto;
}
.overlay-type-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin-top: 16px;
}
.overlay-type-grid > span {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 10px;
  border: 1px solid var(--border-soft);
  border-radius: var(--kinetic-radius-control);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.overlay-type-grid strong {
  font-size: 12px;
}
.overlay-type-grid small {
  color: var(--text-muted);
  font-size: var(--text-2xs);
}

[data-slot="tooltip-content"] {
  border: 1px solid var(--border);
  color: var(--popover-foreground);
  background: var(--popover);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.3);
}

/* Keep the catalog tooltip visually consistent with the collapsed sidebar
   tooltips: compact, tactile, and readable in both themes. */
[data-slot="tooltip-content"].sidebar-matched-tooltip {
  padding: 7px 10px;
  border-radius: var(--kinetic-radius-control);
  color: var(--text);
  background: linear-gradient(155deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-overlay);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.2;
}
/* Sonner renders in a portal, so it needs its own material treatment and must
   not rely on the compact defaults from the library. */
[data-sonner-toast].cn-toast {
  min-height: 64px;
  padding: 14px 16px;
  border: 1px solid color-mix(in srgb, var(--border) 78%, var(--foreground) 12%);
  border-radius: var(--kinetic-radius-menu);
  color: var(--foreground);
  background: linear-gradient(
    155deg,
    color-mix(in srgb, var(--popover) 94%, white 6%),
    var(--popover) 52%,
    var(--secondary)
  );
  box-shadow:
    0 15px 34px rgba(0, 0, 0, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    inset 0 -1px 0 color-mix(in srgb, var(--foreground) 14%, transparent);
  font-family: var(--font-geist-sans), Arial, sans-serif;
}
[data-sonner-toast].cn-toast [data-title] {
  color: var(--foreground) !important;
  font-size: 14px;
  font-weight: 650;
}
[data-sonner-toast].cn-toast [data-description] {
  color: var(--muted-foreground) !important;
  font-size: 12px;
  line-height: 1.4;
}
[data-sonner-toast].cn-toast [data-icon] {
  color: var(--accent);
}

.modal-layer,
.command-layer {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(4, 5, 6, 0.7);
  backdrop-filter: blur(12px);
  animation: fade-in 0.16s ease;
}
.light .modal-layer,
.light .command-layer {
  background: rgba(216, 213, 204, 0.82);
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
}
.dialog-card {
  position: relative;
  width: min(470px, 100%);
  padding: 27px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-panel);
  color: var(--text);
  background: linear-gradient(155deg, var(--surface-top), var(--surface-mid) 48%, var(--surface-bottom));
  box-shadow: var(--shadow-overlay);
  animation: dialog-in 0.22s ease;
}
.dialog-card.kanban-task-dialog {
  width: min(520px, 100%);
}
@keyframes dialog-in {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }
}
.dialog-icon {
  width: 45px;
  height: 45px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 130, 76, 0.35);
  border-radius: var(--kinetic-radius-control);
  color: var(--accent);
  background: var(--accent-soft);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    0 7px 18px var(--accent-glow);
}
.dialog-copy h2 {
  margin: 15px 0 8px;
  font-size: 28px;
}
.dialog-copy p {
  margin: 0;
  color: var(--text-soft);
  font-size: 11px;
  line-height: 1.6;
}
.dialog-summary {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 9px;
  margin-top: 20px;
}
.dialog-summary > span {
  display: grid;
  grid-template-columns: 25px 1fr;
  grid-template-rows: 17px 14px;
  padding: 11px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.dialog-summary svg {
  grid-row: 1 / 3;
  align-self: center;
  color: var(--accent);
}
.dialog-summary strong {
  font-size: var(--text-2xs);
}
.dialog-summary small {
  color: var(--text-muted);
  font-size: var(--text-2xs);
}
.light .dialog-summary small {
  color: #242522;
}
.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  margin-top: 22px;
}
.dialog-close {
  position: absolute;
  top: 14px;
  right: 14px;
}
.drawer-handle {
  display: none;
}

.command-menu {
  width: min(590px, 100%);
  max-height: min(610px, calc(100vh - 40px));
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-panel);
  color: var(--text);
  background: linear-gradient(155deg, var(--surface-top), var(--surface-mid) 48%, var(--surface-bottom));
  box-shadow: var(--shadow-overlay);
  animation: dialog-in 0.2s ease;
}
.command-search {
  height: 58px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 0 17px;
  border-bottom: 1px solid var(--border);
}
.command-search svg {
  color: var(--accent);
}
.command-search input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  color: var(--text);
  background: transparent;
  font-size: var(--text-md);
}
.command-results {
  max-height: 470px;
  overflow-y: auto;
  padding: 8px;
}
.command-label {
  display: block;
  padding: 9px 10px 6px;
  color: var(--text-muted);
  font-size: var(--text-2xs);
  font-weight: 750;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.command-results button,
.command-results a {
  width: 100%;
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px;
  border: 1px solid transparent;
  border-radius: var(--kinetic-radius-control);
  color: var(--text);
  background: transparent;
  text-align: left;
  cursor: pointer;
}
.command-results button:hover,
.command-results a:hover {
  border-color: var(--border);
  background: linear-gradient(180deg, var(--surface-top), var(--surface-bottom));
  box-shadow: var(--shadow-control);
}
.command-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  color: var(--accent);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.command-results button > span:nth-child(2),
.command-results a > span:nth-child(2) {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
}
.command-results .loading-button-content {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
}
.command-results .loading-button-content > span:nth-child(2) {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
}
.command-results strong {
  font-size: var(--text-2xs);
}
.command-results small {
  margin-top: 2px;
  color: var(--text-muted);
  font-size: var(--text-2xs);
}
.command-menu footer {
  display: flex;
  justify-content: space-between;
  padding: 10px 14px;
  border-top: 1px solid var(--border);
  color: var(--text-muted);
  background: var(--surface-inset);
  font-size: var(--text-2xs);
}
.command-menu footer > span {
  display: flex;
  align-items: center;
  gap: 5px;
}

.mobile-scrim {
  display: none;
}

.showcase-overlay-layer {
  position: fixed;
  inset: 0;
  z-index: 110;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(4, 5, 6, 0.7);
  backdrop-filter: blur(12px);
  animation: showcase-overlay-fade 160ms ease;
}
.light .showcase-overlay-layer {
  background: rgba(216, 213, 204, 0.82);
}
@keyframes showcase-overlay-fade {
  from {
    opacity: 0;
  }
}
.showcase-overlay-card {
  position: relative;
  width: min(540px, 100%);
  max-height: min(760px, calc(100svh - 40px));
  overflow: auto;
  padding: 24px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-panel);
  color: var(--text);
  background: linear-gradient(155deg, var(--surface-top), var(--surface-mid) 48%, var(--surface-bottom));
  box-shadow: var(--shadow-overlay);
  animation: showcase-overlay-in 220ms ease;
}
@keyframes showcase-overlay-in {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }
}
.showcase-overlay-card.danger {
  border-color: color-mix(in srgb, var(--danger) 28%, var(--border));
}
.showcase-overlay-handle {
  display: none;
}
.showcase-overlay-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-soft);
}
.showcase-overlay-header .eyebrow {
  color: var(--accent);
  font-size: var(--text-2xs);
  font-weight: 760;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.showcase-overlay-header h2 {
  margin: 7px 0 5px;
  font-family: var(--font-dot-gothic), sans-serif;
  font-size: 27px;
  font-weight: 400;
  line-height: 1.08;
}
.showcase-overlay-header p {
  max-width: 390px;
  margin: 0;
  color: var(--text-soft);
  font-size: var(--text-sm);
  line-height: 1.5;
}
.showcase-overlay-body {
  display: grid;
  gap: 14px;
  padding: 18px 0;
}
.showcase-overlay-footer {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  padding-top: 16px;
  border-top: 1px solid var(--border-soft);
}
.showcase-overlay-footer .button {
  min-width: 112px;
}
.showcase-overlay-form {
  display: grid;
  gap: 13px;
}
.showcase-overlay-form label {
  display: grid;
  gap: 7px;
  color: var(--text-soft);
  font-size: var(--text-xs);
  font-weight: 650;
}
.showcase-overlay-form input,
.showcase-overlay-form textarea {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  color: var(--text);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
  font: inherit;
}
.showcase-overlay-form input {
  height: 41px;
  padding: 0 12px;
}
.showcase-overlay-form textarea {
  min-height: 92px;
  padding: 10px 12px;
  resize: vertical;
}
.showcase-overlay-form :is(input, textarea):focus {
  border-color: var(--accent);
  outline: none;
  box-shadow:
    var(--shadow-inset),
    0 0 0 3px var(--accent-soft);
}
.overlay-input-with-icon {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.overlay-input-with-icon:focus-within {
  border-color: var(--accent);
  box-shadow:
    var(--shadow-inset),
    0 0 0 3px var(--accent-soft);
}
.overlay-input-with-icon svg {
  flex: none;
  color: var(--text-muted);
}
.overlay-input-with-icon input {
  height: 39px;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}
.overlay-input-with-icon input:focus {
  box-shadow: none;
}
.overlay-form-note,
.overlay-password-hint {
  margin: -3px 0 0;
  color: var(--text-muted);
  font-size: var(--text-2xs);
  line-height: 1.5;
}
.overlay-password-hint strong {
  color: var(--text-soft);
}
.overlay-detail-list {
  display: grid;
  gap: 14px;
}
.overlay-detail-owner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.overlay-detail-owner > span {
  display: grid;
  gap: 3px;
}
.overlay-detail-owner strong {
  font-size: var(--text-sm);
}
.overlay-detail-owner small {
  color: var(--text-muted);
  font-size: var(--text-2xs);
}
.overlay-detail-list dl {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
  margin: 0;
}
.overlay-detail-list dl > div {
  display: grid;
  gap: 4px;
  padding: 11px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.overlay-detail-list dt {
  color: var(--text-muted);
  font-size: var(--text-2xs);
}
.overlay-detail-list dd {
  margin: 0;
  color: var(--text);
  font-size: var(--text-sm);
  font-weight: 700;
}
.overlay-confirmation-copy {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  align-items: center;
  column-gap: 13px;
  row-gap: 4px;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
  text-align: left;
}
.overlay-confirmation-copy.compact {
  margin-bottom: 1px;
}
.overlay-confirmation-icon {
  grid-row: 1 / span 2;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 38%, var(--border));
  border-radius: 50%;
  color: var(--accent);
  background: var(--accent-soft);
  box-shadow: var(--shadow-control);
}
.overlay-confirmation-icon.danger {
  border-color: color-mix(in srgb, var(--danger) 38%, var(--border));
  color: var(--danger);
  background: color-mix(in srgb, var(--danger) 12%, var(--surface-inset));
}
.overlay-confirmation-icon.success {
  border-color: color-mix(in srgb, var(--success) 46%, var(--border));
  color: var(--success);
  background: color-mix(in srgb, var(--success) 12%, var(--surface-inset));
}
.overlay-confirmation-copy p {
  grid-column: 2;
  margin: 0;
  color: var(--text);
  font-size: var(--text-md);
  font-weight: 700;
}
.overlay-confirmation-copy small {
  grid-column: 2;
  max-width: none;
  color: var(--text-muted);
  font-size: var(--text-xs);
  line-height: 1.55;
}
.overlay-settings-list {
  display: grid;
  gap: 9px;
}
.overlay-settings-list label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-control);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
}
.overlay-settings-list label > span {
  display: grid;
  gap: 3px;
}
.overlay-settings-list .overlay-settings-copy {
  min-width: 0;
}
.overlay-settings-list strong {
  font-size: var(--text-sm);
}
.overlay-settings-list small {
  color: var(--text-muted);
  font-size: var(--text-2xs);
}
.overlay-checkbox {
  position: relative;
  width: 20px;
  height: 20px;
  flex: none;
  display: grid;
  place-items: center;
}
.overlay-checkbox input {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}
.overlay-checkbox-control {
  position: relative;
  width: 20px;
  height: 20px;
  display: block;
  border: 1px solid var(--border);
  border-radius: var(--kinetic-radius-xs);
  background: var(--surface-inset);
  box-shadow: var(--shadow-inset);
  transition:
    transform 120ms ease,
    border-color 120ms ease,
    background 120ms ease,
    box-shadow 120ms ease;
}
.overlay-checkbox-control::after {
  content: "";
  position: absolute;
  left: 6px;
  top: 3px;
  width: 5px;
  height: 9px;
  border: solid var(--action-foreground);
  border-width: 0 2px 2px 0;
  opacity: 0;
  transform: rotate(45deg) scale(0.7);
  transition:
    opacity 120ms ease,
    transform 160ms ease;
}
.overlay-checkbox input:checked + .overlay-checkbox-control {
  border-color: var(--accent);
  background: linear-gradient(180deg, var(--action-top), var(--action-bottom));
  box-shadow:
    0 4px 9px var(--accent-glow),
    inset 0 1px 0 rgba(255, 255, 255, 0.34);
}
.overlay-checkbox input:checked + .overlay-checkbox-control::after {
  opacity: 1;
  transform: rotate(45deg) scale(1);
}
.overlay-checkbox input:active + .overlay-checkbox-control {
  transform: translateY(1px) scale(0.95);
}
.overlay-checkbox input:focus-visible + .overlay-checkbox-control {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.overlay-checkbox input:disabled + .overlay-checkbox-control {
  opacity: 0.55;
  cursor: not-allowed;
}
.overlay-checkbox input:disabled {
  cursor: not-allowed;
}
.overlay-checkbox input:checked:active + .overlay-checkbox-control {
  box-shadow:
    inset 0 2px 4px color-mix(in srgb, var(--action-bottom) 65%, transparent),
    0 0 9px var(--accent-glow);
}
.overlay-checkbox input {
  appearance: none;
}
.overlay-checkbox-control {
  pointer-events: none;
}
.overlay-checkbox {
  align-self: center;
}

@media (max-width: 980px) {
  .overlay-action-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .showcase-overlay-layer {
    place-items: end center;
    padding: 0;
  }
  .showcase-overlay-card {
    width: 100%;
    max-height: min(88svh, 760px);
    padding: 24px 20px calc(20px + env(safe-area-inset-bottom));
    border-radius: var(--kinetic-radius-panel) var(--kinetic-radius-panel) 0 0;
    animation: showcase-drawer-in 240ms cubic-bezier(0.22, 1, 0.36, 1);
  }
  @keyframes showcase-drawer-in {
    from {
      transform: translateY(100%);
    }
  }
  .showcase-overlay-handle {
    display: block;
    width: 42px;
    height: 4px;
    margin: -12px auto 18px;
    border-radius: var(--kinetic-radius-pill);
    background: var(--text-muted);
    opacity: 0.55;
  }
  .showcase-overlay-footer {
    flex-direction: column-reverse;
  }
  .showcase-overlay-footer .button {
    width: 100%;
  }
  .overlay-gallery-intro {
    align-items: flex-start;
    flex-direction: column;
  }
  .overlay-gallery-mode-desktop {
    display: none;
  }
  .overlay-gallery-mode-mobile {
    display: inline;
  }
}

@media (max-width: 480px) {
  .overlay-action-grid {
    grid-template-columns: 1fr;
  }
  .overlay-detail-list dl {
    grid-template-columns: 1fr;
  }
}
